JSON.parse(src).data.forEach(chapter => {
    const { chapter: chap, updatedAt, translatedLanguage } = chapter.attributes;
    const url = chapter.id;

    if (!seenChapters.has(chap)) {
        seenChapters.add(chap);
        lists_.push({
            title: `第${chap}章 分译`, 
            url : "",
            volume: 1
        });
        volumeCounter[chap] = 0;
